isVisible:
{{
  [
    'MATÉRIEL NEUF', 'MATERIEL NEUF', 'ROBOT',
    'MATÉRIEL BATTERIE', 'MATERIEL BATTERIE',
    'OCCASION', 'OCCASION TVA SUR MARGE'
  ].includes((Get_Detail_Article.data?.[0]?.Famille || '').trim().toUpperCase())
}}

onFilesSelected:
{{
  (async () => {
    if (!fp_eclate_article.files?.length) return;
    try {
      await API_Envoyer_Eclate_N8N.run();
      resetWidget('fp_eclate_article', true);
      showAlert('⏳ PDF envoyé vers Google Drive, mise à jour en cours...', 'info');
      setTimeout(() => {
        Get_Detail_Article.run();
      }, 4000);
    } catch (err) {
      showAlert('❌ Erreur envoi : ' + (err.message || err), 'error');
    }
  })()
}}
